// Package notifier manages the devices, addresses, and preferences that make
// up the GHATD notification system.
//
// The package keeps track of two things for each user:
//
//  1. Notification addresses – the actual destinations where notifications land
//     (a browser tab via Web Push, or a mobile phone via Firebase).
//  2. Notification preferences – which channels a user wants to hear from and
//     whether they want notifications at all.
//
// The data model is designed so the same browser or mobile token can move
// between users without duplicates, and sensitive information like Push API
// endpoints and FCM tokens never leak into client-facing API responses.
//
// # Channels
//
// The package supports two delivery channels today:
//
//   - WEBPUSH – modern browsers that support the Push API. A user subscribes
//     their browser and GHATD delivers notifications through VAPID-authenticated
//     Web Push messages.
//   - FCM – Firebase Cloud Messaging for Android and iOS devices. The plumbing
//     for token registration is built in, but real Firebase delivery will be
//     enabled when Firebase credentials are available later.
//
// # Address Lifecycle
//
// When a browser registers a Push subscription or a mobile app sends its
// FCM token, the package stores it as a NotificationAddress. The address
// contains:
//
//   - A unique ID so clients can refer to their own addresses.
//   - The user ID that owns this address.
//   - The channel (WEBPUSH or FCM).
//   - The status (ACTIVE means "send here please", DISABLED means "keep this
//     around but don't send").
//   - An address hash – a SHA-256 fingerprint of the channel plus the address
//     identity (endpoint or token). This is used for deduplication so the
//     same browser always points to the latest signed-in user.
//   - Channel-specific payloads (WebPush has endpoint and keys, FCM has a
//     token).
//
// When an address is returned to a client (the browser or mobile app), the
// package creates a sanitised summary that hides the endpoint and keys so
// they are never exposed over the API.
//
// # Preferences
//
// Each user gets a NotificationPreferences document keyed by their user ID.
// New users default to "enabled for all channels." A user can later disable
// notifications entirely or disable individual channels (for example "stop
// sending me push notifications but keep email").
package notifier

import "strings"

// NotificationChannel names a notification delivery provider.
//
// Think of channels like different "roads" a notification travels down
// to reach a user – one road for browsers (Web Push) and another road
// for mobile phones (FCM).
type NotificationChannel string

// NotificationAddressStatus tells you whether a notification destination
// is ready to receive messages.
//
//   - ACTIVE means "yes, send notifications here."
//   - DISABLED means "keep the address on file, but don't send anything."
type NotificationAddressStatus string

// WebPushKeys holds the public encryption keys for a browser Push API
// subscription.
//
// These keys are generated by the browser when the user grants permission
// and subscribes. GHATD uses them to encrypt push messages so only the
// subscribing browser can read them.
//
//   - P256DH is the client's public Elliptic Curve Diffie-Hellman key.
//   - Auth is an authentication secret generated by the browser.
type WebPushKeys struct {
	P256DH string `json:"p256dh" bson:"p256dh"`
	Auth   string `json:"auth" bson:"auth"`
}

// WebPushAddress stores a complete Push API subscription from a browser.
//
// When a user clicks "Enable notifications" in the web app, the browser
// generates a subscription that includes an endpoint URL (where GHATD
// posts messages) and the encryption keys needed to secure them.
type WebPushAddress struct {
	Endpoint string      `json:"endpoint" bson:"endpoint"`
	Keys     WebPushKeys `json:"keys" bson:"keys"`
}

// FCMAddress stores a Firebase Cloud Messaging device token.
//
// Mobile apps receive a unique token from Firebase that identifies this
// specific installation of the app. GHATD stores this token so it can
// send push notifications through Firebase to that device.
type FCMAddress struct {
	Token string `json:"token" bson:"token"`
}

// NotificationAddressMetadata records when an address was created, last
// updated, and last seen.
//
// "Last seen" is updated every time the device registers, so inactive
// devices can be identified and cleaned up later.
type NotificationAddressMetadata struct {
	CreatedAt  string `json:"created_at,omitempty" bson:"created_at,omitempty"`
	UpdatedAt  string `json:"updated_at,omitempty" bson:"updated_at,omitempty"`
	LastSeenAt string `json:"last_seen_at,omitempty" bson:"last_seen_at,omitempty"`
}

// NotificationAddress links one notification destination to a user.
//
// This is the core record in the notification system. Each address
// represents one "place" where a user can receive notifications –
// a specific browser tab, a mobile app installation, and so on.
//
// The AddressHash field is computed from the channel and identity
// (endpoint or token) and is never sent to clients (the JSON tag is
// explicitly "-"). It is used inside the database to prevent duplicate
// addresses when the same browser registers again.
type NotificationAddress struct {
	ID          string                       `json:"id" bson:"_id"`
	UserID      string                       `json:"user_id" bson:"user_id"`
	Channel     NotificationChannel          `json:"channel" bson:"channel"`
	Status      NotificationAddressStatus    `json:"status" bson:"status"`
	AddressHash string                       `json:"-" bson:"address_hash"`
	DeviceID    string                       `json:"device_id,omitempty" bson:"device_id,omitempty"`
	DeviceName  string                       `json:"device_name,omitempty" bson:"device_name,omitempty"`
	Platform    string                       `json:"platform,omitempty" bson:"platform,omitempty"`
	WebPush     *WebPushAddress              `json:"webpush,omitempty" bson:"webpush,omitempty"`
	FCM         *FCMAddress                  `json:"fcm,omitempty" bson:"fcm,omitempty"`
	Metadata    *NotificationAddressMetadata `json:"metadata,omitempty" bson:"metadata,omitempty"`
}

// NotificationAddressSummary is the safe, client-friendly version of a
// NotificationAddress.
//
// When a user asks "show me my registered devices," the API returns a
// summary. Unlike the full NotificationAddress, a summary never includes
// the Push API endpoint, encryption keys, or FCM token. This keeps the
// secrets on the server where they belong.
type NotificationAddressSummary struct {
	ID         string                    `json:"id"`
	Channel    NotificationChannel       `json:"channel"`
	Status     NotificationAddressStatus `json:"status"`
	DeviceID   string                    `json:"device_id,omitempty"`
	DeviceName string                    `json:"device_name,omitempty"`
	Platform   string                    `json:"platform,omitempty"`
	CreatedAt  string                    `json:"created_at,omitempty"`
	UpdatedAt  string                    `json:"updated_at,omitempty"`
	LastSeenAt string                    `json:"last_seen_at,omitempty"`
}

// NotificationPreferencesMetadata records when user preferences were
// first created and last changed.
type NotificationPreferencesMetadata struct {
	CreatedAt string `json:"created_at,omitempty" bson:"created_at,omitempty"`
	UpdatedAt string `json:"updated_at,omitempty" bson:"updated_at,omitempty"`
}

// NotificationPreferences stores a user's choices about notifications.
//
// Preferences are keyed by user ID and stored in their own collection,
// separate from the core user record. This keeps the user table clean
// and allows the notification system to evolve independently.
//
// Default values for new users:
//   - Enabled: true (notifications are on)
//   - All channels: enabled (both Web Push and FCM)
//
// A user can change these at any time. If Enabled is false, no
// notifications will be delivered on any channel, regardless of the
// per-channel settings.
type NotificationPreferences struct {
	UserID   string                           `json:"user_id" bson:"_id"`
	Enabled  bool                             `json:"enabled" bson:"enabled"`
	Channels map[string]bool                  `json:"channels" bson:"channels"`
	Metadata *NotificationPreferencesMetadata `json:"metadata,omitempty" bson:"metadata,omitempty"`
}

// NotifierConfig tells client applications what they can do with
// notifications on this server.
//
// Clients fetch this config before trying to register a push subscription
// so they know:
//
//   - Which channels are supported (e.g. WEBPUSH is available, FCM is not).
//   - Whether Web Push is enabled and what the VAPID public key is
//     (needed to subscribe the browser to push).
//   - Whether FCM is enabled (so mobile apps know if they can register).
//
// This config is public and safe to cache on the client.
type NotifierConfig struct {
	SupportedChannels []NotificationChannel `json:"supported_channels"`
	WebPush           WebPushClientConfig   `json:"webpush"`
	FCM               FCMClientConfig       `json:"fcm"`
}

// WebPushClientConfig contains the information a browser needs to
// subscribe to push notifications.
//
//   - Enabled: whether the server is ready to accept Web Push registrations.
//   - VAPIDPublicKey: the server's public key. The browser uses this when
//     calling pushManager.subscribe() so it knows which server is allowed
//     to send it notifications.
type WebPushClientConfig struct {
	Enabled        bool   `json:"enabled"`
	VAPIDPublicKey string `json:"vapid_public_key,omitempty"`
}

// FCMClientConfig tells mobile apps whether Firebase messaging is
// available on this server.
type FCMClientConfig struct {
	Enabled bool `json:"enabled"`
}

// Sanitise returns a client-safe summary without endpoint or token secrets.
//
// The full NotificationAddress contains sensitive information like the
// Push API endpoint and encryption keys. When the server lists a user's
// registered devices, it calls Sanitise() on each address first so the
// response only includes the fields a client needs (ID, channel, status,
// device info, and timestamps).
func (a NotificationAddress) Sanitise() NotificationAddressSummary {
	summary := NotificationAddressSummary{
		ID:         a.ID,
		Channel:    a.Channel,
		Status:     a.Status,
		DeviceID:   a.DeviceID,
		DeviceName: a.DeviceName,
		Platform:   a.Platform,
	}

	if a.Metadata != nil {
		summary.CreatedAt = a.Metadata.CreatedAt
		summary.UpdatedAt = a.Metadata.UpdatedAt
		summary.LastSeenAt = a.Metadata.LastSeenAt
	}

	return summary
}

// Normalised returns the canonical uppercase form of a channel name.
//
// Channel names can arrive with mixed casing from different clients
// (e.g. "webpush", "WebPush", "WEBPUSH"). Normalised() converts them
// all to the same canonical form ("WEBPUSH") so comparisons work
// reliably everywhere in the package.
func (c NotificationChannel) Normalised() NotificationChannel {
	return NotificationChannel(strings.ToUpper(strings.TrimSpace(string(c))))
}

// IsSupported returns true when the notifier package knows how to
// handle this channel.
//
// Currently supported channels are WEBPUSH and FCM. Unknown channels
// are rejected early so invalid data never reaches the database.
func (c NotificationChannel) IsSupported() bool {
	switch c.Normalised() {
	case NotificationChannelWebPush, NotificationChannelFCM:
		return true
	default:
		return false
	}
}

// DefaultNotificationPreferences returns the "opt in to everything"
// starting point for a new user's notification settings.
//
// A real user may not have any preferences document stored yet.
// When that happens, the service returns these defaults:
//   - Notifications are enabled globally.
//   - All channels (Web Push and FCM) are enabled individually.
func DefaultNotificationPreferences(userID string) *NotificationPreferences {
	return &NotificationPreferences{
		UserID:  userID,
		Enabled: true,
		Channels: map[string]bool{
			string(NotificationChannelWebPush): true,
			string(NotificationChannelFCM):     true,
		},
	}
}
